function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each nums value is an integer from 1 to 10^9.';
  if (queries.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each query is an integer from 1 to 10^9.';
  return null;
}

