function minOperations(nums, queries) {
  const sorted = [...nums].sort((a, b) => a - b);
  const n = sorted.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + sorted[i];
  }
  const answer = [];
  for (const query of queries) {
    let left = 0;
    let right = n;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < query) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    const below = query * left - prefix[left];
    const above = prefix[n] - prefix[left] - query * (n - left);
    answer.push(below + above);
  }
  return answer;
}

