function generate(rand, size) {
  if (size === 'large') {
    const span = rand() < 0.5 ? 1000000000 : 1000;
    const pick = () => 1 + Math.floor(rand() * span);
    const nums = Array.from({ length: 2000 }, pick);
    const queries = Array.from({ length: 2000 }, pick);
    return [nums, queries];
  }
  const n = 1 + Math.floor(rand() * 8);
  const m = 1 + Math.floor(rand() * 5);
  const span = rand() < 0.3 ? 3 : 20;
  const pick = () => 1 + Math.floor(rand() * span);
  return [Array.from({ length: n }, pick), Array.from({ length: m }, pick)];
}
